<?php require 'config.php';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $acao=$_POST['acao'] ?? '';
 if($acao==='add_func'){ $f=jread('funcionarios',[]); $f[]=['id'=>uniqid('fun_'),'nome'=>trim($_POST['nome']),'cargo'=>trim($_POST['cargo']??'Funcionário'),'ativo'=>1]; jwrite('funcionarios',$f); log_event('funcionario','Funcionário cadastrado',['nome'=>$_POST['nome']??'']); }
 if($acao==='del_func'){ $f=array_values(array_filter(jread('funcionarios',[]),fn($x)=>$x['id']!==$_POST['id'])); jwrite('funcionarios',$f); log_event('funcionario','Funcionário removido',['id'=>$_POST['id']??'']); }
 if($acao==='vincular'){ $disp=jread('dispositivos',[]); foreach($disp as &$d){ if($d['id']===$_POST['dev_id']) $d['funcionario_id']=$_POST['funcionario_id']; } jwrite('dispositivos',$disp); }
 if($acao==='remover_dev'){ $disp=array_values(array_filter(jread('dispositivos',[]),fn($x)=>$x['id']!==$_POST['dev_id'])); jwrite('dispositivos',$disp); }
 if($acao==='config'){
   $old=jread('config',[]); jwrite('config',[
    'jornada_horas'=>(float)$_POST['jornada_horas'], 'tolerancia_offline_min'=>(int)$_POST['tolerancia_offline_min'],
    'leituras_entrada'=>(int)($_POST['leituras_entrada']??2), 'leituras_saida'=>(int)($_POST['leituras_saida']??3),
    'hora_entrada'=>$_POST['hora_entrada'], 'hora_saida'=>$_POST['hora_saida'], 'ip_pc'=>trim($_POST['ip_pc'] ?? ($old['ip_pc'] ?? '192.168.0.100')),
    'almoco_ativo'=>isset($_POST['almoco_ativo'])?1:0, 'almoco_inicio'=>$_POST['almoco_inicio'] ?? '12:00', 'almoco_fim'=>$_POST['almoco_fim'] ?? '14:30',
    'almoco_minutos'=>(int)($_POST['almoco_minutos'] ?? 60), 'almoco_minimo_trabalho_min'=>(int)($_POST['almoco_minimo_trabalho_min'] ?? 360), 'almoco_excedente_extra'=>isset($_POST['almoco_excedente_extra'])?1:0,
    'alerta_sem_detectar_min'=>(int)($_POST['alerta_sem_detectar_min'] ?? 30), 'hora_entrada_limite'=>$_POST['hora_entrada_limite'] ?? '08:10', 'inteligencia_ativa'=>isset($_POST['inteligencia_ativa'])?1:0
   ]); set_token($_POST['token']); log_event('config','Configurações alteradas');
 }
 if($acao==='novo_cadastro'){
   $cad=jread('cadastros',[]); $codigo=strtoupper(substr(bin2hex(random_bytes(3)),0,6));
   $cad[$codigo]=['codigo'=>$codigo,'funcionario_id'=>$_POST['funcionario_id'],'criado_em'=>now(),'expira_em'=>date('Y-m-d H:i:s',time()+900),'status'=>'aguardando','ip'=>'','mac'=>'','device_uid'=>'','user_agent'=>'','apelido'=>''];
   jwrite('cadastros',$cad); header('Location: configuracoes.php?cadastro='.$codigo); exit;
 }
 if($acao==='cancelar_cadastro'){ $cad=jread('cadastros',[]); unset($cad[$_POST['codigo']]); jwrite('cadastros',$cad); }
 header('Location: configuracoes.php'); exit;
}
header_page('Configurações'); $funs=jread('funcionarios',[]); $disp=jread('dispositivos',[]); $conf=jread('config',[]); $cad=jread('cadastros',[]); $codigoAtual=$_GET['cadastro'] ?? ''; $cadAtual=$codigoAtual && isset($cad[$codigoAtual]) ? $cad[$codigoAtual] : null;
?>
<div class="grid"><div class="card"><h2>Adicionar funcionário</h2><form method="post"><input type="hidden" name="acao" value="add_func"><label>Nome</label><input name="nome" required><label>Cargo</label><input name="cargo" value="Funcionário"><button>Salvar</button></form></div><div class="card"><h2>Regras do ponto</h2><form method="post"><input type="hidden" name="acao" value="config"><label>Token do leitor</label><input name="token" value="<?=h(token_atual())?>"><label>IP do PC da loja</label><input name="ip_pc" value="<?=h($conf['ip_pc']??'192.168.0.100') ?>" placeholder="192.168.0.100"><div class="twocol"><div><label>Jornada diária em horas</label><input name="jornada_horas" value="<?=h($conf['jornada_horas']??8)?>"></div><div><label>Tolerância offline em minutos</label><input name="tolerancia_offline_min" value="<?=h($conf['tolerancia_offline_min']??15)?>"></div></div><div class="twocol"><div><label>Leituras para entrada</label><input type="number" name="leituras_entrada" value="<?=h($conf['leituras_entrada']??2)?>"></div><div><label>Leituras para saída</label><input type="number" name="leituras_saida" value="<?=h($conf['leituras_saida']??3)?>"></div></div><div class="twocol"><div><label>Entrada padrão</label><input type="time" name="hora_entrada" value="<?=h($conf['hora_entrada']??'08:00')?>"></div><div><label>Saída padrão</label><input type="time" name="hora_saida" value="<?=h($conf['hora_saida']??'18:00')?>"></div></div><hr><h3>Almoço inteligente</h3><label class="check"><input type="checkbox" name="almoco_ativo" value="1" <?=!empty($conf['almoco_ativo'])?'checked':''?>> Descontar almoço automaticamente</label><div class="twocol"><div><label>Janela começa</label><input type="time" name="almoco_inicio" value="<?=h($conf['almoco_inicio']??'12:00')?>"></div><div><label>Janela termina</label><input type="time" name="almoco_fim" value="<?=h($conf['almoco_fim']??'14:30')?>"></div></div><div class="twocol"><div><label>Desconto padrão em minutos</label><input type="number" name="almoco_minutos" value="<?=h($conf['almoco_minutos']??60)?>"></div><div><label>Descontar só após X min trabalhados</label><input type="number" name="almoco_minimo_trabalho_min" value="<?=h($conf['almoco_minimo_trabalho_min']??360)?>"></div></div><label class="check"><input type="checkbox" name="almoco_excedente_extra" value="1" <?=!empty($conf['almoco_excedente_extra'])?'checked':''?>> Se passar do almoço, descontar tempo real detectado</label><p class="notice">Durante a janela de almoço, queda do Wi‑Fi vira pausa de almoço, não saída definitiva.</p><hr><h3>Inteligência e alertas</h3><label class="check"><input type="checkbox" name="inteligencia_ativa" value="1" <?=!empty($conf['inteligencia_ativa'])?'checked':''?>> Ativar alertas inteligentes</label><div class="twocol"><div><label>Alertar sem detectar após X min</label><input type="number" name="alerta_sem_detectar_min" value="<?=h($conf['alerta_sem_detectar_min']??30)?>"></div><div><label>Horário limite de entrada</label><input type="time" name="hora_entrada_limite" value="<?=h($conf['hora_entrada_limite']??'08:10')?>"></div></div><button>Salvar configuração</button></form></div></div><br>
